-- Ribbon TERRAIN as REAL noise-driven map-gen (§4, §15-2; ci-3yl rewrite).
--
-- The ribbon is generated by the MAP-GEN itself, not by an on_chunk_generated
-- script. This module is the single source of truth for the tile BANDS: it maps
-- the perpendicular (sunward-nightward) axis to a set of Cindra-exclusive tiles,
-- each placed by a Factorio NOISE EXPRESSION keyed to that axis. The engine picks,
-- per tile, the candidate with the highest `probability_expression`, so the bands
-- arrange themselves; a smooth `basis_noise` term is added to the axis coordinate
-- so every band boundary is an ORGANIC wavy curve, never a raw straight line.
--
-- Gradient, from the HOT (sunward) edge inward to the COLD (nightward) edge -- the
-- planet's whole thesis painted onto the ground:
--
--   lava  ->  molten-rock  ->  [ terminator ]  ->  frost  ->  ice
--   (lethal)  (walkable/safe)   (temperate)        (safe)     (lethal)
--
-- Only the LAVA and ICE bands are lethal (scripts/tile-damage.lua reads
-- M.lethal_kind); molten-rock and frost are the WALKABLE, buildable, SAFE margins
-- (ci-3yl: "walkable molten rock -- only actual lava damages"). The terminator
-- band at the centre is the wide safe spawn.
--
-- The world is finite PERPENDICULAR to the ribbon via the map-gen's own `width`
-- (vertical orientation) / `height` (horizontal): the engine fills everything
-- beyond +/- WIDTH/2 with `out-of-map`, so the void backstop emerges from the
-- map-gen, not a script. See M.finite_dimension / prototypes/planet.lua.
--
-- PURE where it counts: the *_expr emitters and lethal_kind are plain string/table
-- logic (no game.* / prototypes.*), so the bands are unit-testable off the game
-- (unit-tests/test_terrain.lua). The clone-source table is consumed only at the
-- data stage (prototypes/tiles.lua). Boundaries read the SAME ribbon config as
-- scripts/ribbon.lua, so the VISIBLE terrain and the FELT damage share one axis.

local ribbon = require("scripts.ribbon")
local axis = require("scripts.axis")

local M = {}

-- The Cindra tiles, ordered centre -> edge on each side. Each is a NEW `cindra-*`
-- prototype cloned (prototypes/tiles.lua) from a vanilla tile for its art; we
-- never enable or mutate the vanilla tile itself, so nothing leaks onto Nauvis.
-- `lethal` marks the tiles scripts/tile-damage.lua damages entities on.
--   name        clone_from             lethal    role
M.TILES = {
  { name = "cindra-terminator",  clone_from = "volcanic-soil-light", lethal = nil,    role = "center" },
  { name = "cindra-molten-rock", clone_from = "volcanic-cracks-hot", lethal = nil,    role = "hot_margin" },
  { name = "cindra-lava",        clone_from = "lava",                lethal = "heat", role = "hot_edge" },
  { name = "cindra-frost",       clone_from = "snow-flat",           lethal = nil,    role = "cold_margin" },
  { name = "cindra-deep-ice",    clone_from = "ice-rough",           lethal = "cold", role = "cold_edge" },
}

-- Convenience lookups.
M.CENTER = "cindra-terminator"
M.NAME = {}
for _, t in ipairs(M.TILES) do M.NAME[t.role] = t.name end

-- Smooth-noise amplitude (tiles) and wavelength (tiles) that wiggles every band
-- boundary so the bands are organic, never straight. Fixed seeds -> the ribbon
-- has the same band structure on every map seed (a ribbon world is a fixed shape,
-- not a per-seed lottery), and it stays deterministic for tests. (tune)
M.NOISE_AMPLITUDE = 7
M.NOISE_WAVELENGTH = 48

-- The signed perpendicular axis as a noise-expression string (sunward-positive =
-- hot), and its negation (nightward-positive = cold). scripts/axis.lua owns which
-- world axis is perpendicular; we never re-derive it.
local function perp_expr() return axis.perp_expr() end
local function perp_neg_expr() return axis.perp_neg_expr() end

-- Format a number for the noise DSL (integers stay clean, no float noise).
local function num(v)
  if v == math.floor(v) then return string.format("%d", v) end
  return string.format("%.6g", v)
end

-- A smooth basis-noise term ~+/-NOISE_AMPLITUDE tiles at ~NOISE_WAVELENGTH pitch.
-- `seed1` varies the field so the hot and cold boundaries wiggle independently.
local function noise(seed1)
  return "basis_noise{x = x, y = y, seed0 = 1, seed1 = " .. num(seed1) ..
         ", input_scale = " .. num(1 / M.NOISE_WAVELENGTH) ..
         ", output_scale = " .. num(M.NOISE_AMPLITUDE) .. "}"
end

-- range_select_base(input, from, to, slope, min, max): 0 at the from/to markers,
-- rising to `max` inside. Our band selector.
local function rsb(input, from, to, slope, lo, hi)
  return "range_select_base(" .. input .. ", " .. num(from) .. ", " .. num(to) ..
         ", " .. num(slope) .. ", " .. num(lo) .. ", " .. num(hi) .. ")"
end

-- Perturbed axis coordinates (raw axis + organic noise), one per side.
local function hot_depth() return "(" .. perp_expr() .. " + " .. noise(11) .. ")" end
local function cold_depth() return "(" .. perp_neg_expr() .. " + " .. noise(12) .. ")" end

-- The `probability_expression` string for a Cindra tile, given the ribbon config.
-- Peaks (2 for the safe margins, 3 for the lethal edges) sit above the centre
-- tile's constant baseline of 1, so a margin/edge tile wins inside its band and
-- the terminator wins everywhere else -- guaranteeing full coverage (the engine
-- has no default tile; one candidate must always win). Bands overlap so no strip
-- of centre ground ever bleeds between two coloured bands.
function M.probability_expr(name, cfg)
  local c = ribbon.resolve(cfg)
  local S, L, W = c.safe_half_width, c.lethal_at, c.wall_at
  local hot, cold = hot_depth(), cold_depth()
  if name == "cindra-terminator" then
    return "1" -- constant baseline: the wide safe spawn + the universal fallback.
  elseif name == "cindra-molten-rock" then
    return rsb(hot, S - 6, L + 16, 6, 0, 2)
  elseif name == "cindra-lava" then
    return rsb(hot, L - 8, W + 64, 6, 0, 3)
  elseif name == "cindra-frost" then
    return rsb(cold, S - 6, L + 16, 6, 0, 2)
  elseif name == "cindra-deep-ice" then
    return rsb(cold, L - 8, W + 64, 6, 0, 3)
  end
  error("terrain: unknown Cindra tile " .. tostring(name))
end

-- "heat" / "cold" / nil: the damage kind a lethal tile inflicts (nil = safe).
-- scripts/tile-damage.lua reads this to damage everything standing on a lethal
-- tile; the two safe margins (molten-rock, frost) return nil.
function M.lethal_kind(name)
  for _, t in ipairs(M.TILES) do
    if t.name == name then return t.lethal end
  end
  return nil
end

-- The set of every lethal tile name -> its damage kind (built once).
function M.lethal_tiles()
  local out = {}
  for _, t in ipairs(M.TILES) do
    if t.lethal then out[t.name] = t.lethal end
  end
  return out
end

-- All Cindra tile names (for the map-gen autoplace_settings.tile allow-list).
function M.tile_names()
  local out = {}
  for _, t in ipairs(M.TILES) do out[#out + 1] = t.name end
  return out
end

-- The FINITE map dimension (tiles) that bounds the ribbon perpendicular to its
-- long axis, and which basic setting it maps to. The engine voids everything
-- beyond +/- dim/2, so the ribbon is finite perpendicular straight from the
-- map-gen. Vertical ribbon -> bound X (`width`); horizontal -> bound Y (`height`).
function M.finite_dimension(cfg)
  local c = ribbon.resolve(cfg)
  return {
    key = (axis.orientation() == axis.HORIZONTAL) and "height" or "width",
    value = 2 * c.wall_at,
  }
end

return M
